-- W8b slice 1: route-aware booking (plan W8b-ROUTE-BOOKING-PLAN-2026-11-10, Áron's decisions 2026-11-10).
-- Additive only: one new reference table, nullable columns on tasks, two columns
-- with a false/NULL default on equipment, one bookable machine for tenant 1.
-- No existing row changes value (equipment.bookable defaults to false).
--
-- Rollback (in this order):
--   ALTER TABLE "tasks" DROP COLUMN "site_settlement_id", DROP COLUMN "site_address",
--     DROP COLUMN "site_source", DROP COLUMN "equipment_id", DROP COLUMN "override_reason";
--   DELETE FROM "equipment" WHERE "bookable" = true AND "name" = 'BetonRadar 1' AND "tenant_id" = 1;
--   ALTER TABLE "equipment" DROP COLUMN "base_settlement_id", DROP COLUMN "bookable";
--   DROP TABLE "hu_settlements";

CREATE TABLE "hu_settlements" (
    "id" SERIAL NOT NULL,
    "name" TEXT NOT NULL,
    "county" TEXT NOT NULL,
    "district" SMALLINT,
    "lat" DOUBLE PRECISION NOT NULL,
    "lng" DOUBLE PRECISION NOT NULL,
    "postcodes" TEXT[] DEFAULT ARRAY[]::TEXT[],
    CONSTRAINT "hu_settlements_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "hu_settlements_district_check" CHECK ("district" IS NULL OR "district" BETWEEN 1 AND 23)
);
CREATE INDEX "hu_settlements_postcodes_idx" ON "hu_settlements" USING GIN ("postcodes");

-- A machine is bookable equipment with a base (where its day starts and ends).
ALTER TABLE "equipment" ADD COLUMN "bookable" BOOLEAN NOT NULL DEFAULT false,
    ADD COLUMN "base_settlement_id" INTEGER;
ALTER TABLE "equipment" ADD CONSTRAINT "equipment_base_settlement_id_fkey"
    FOREIGN KEY ("base_settlement_id") REFERENCES "hu_settlements"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Every booking has its own job site and its own machine.
ALTER TABLE "tasks" ADD COLUMN "site_settlement_id" INTEGER,
    ADD COLUMN "site_address" TEXT,
    ADD COLUMN "site_source" TEXT,
    ADD COLUMN "equipment_id" INTEGER,
    ADD COLUMN "override_reason" TEXT;
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_site_source_check"
    CHECK ("site_source" IS NULL OR "site_source" IN ('stated', 'permit', 'tender', 'premises', 'company_address_assumed'));
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_site_settlement_id_fkey"
    FOREIGN KEY ("site_settlement_id") REFERENCES "hu_settlements"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_equipment_id_fkey"
    FOREIGN KEY ("equipment_id") REFERENCES "equipment"("id") ON DELETE SET NULL ON UPDATE CASCADE;

