SELECT setval(pg_get_serial_sequence('"hu_settlements"','id'), (SELECT MAX("id") FROM "hu_settlements"));

-- The one machine today (plan A1/A2): base = Érd until Péter names the real start point.
INSERT INTO "equipment" ("tenant_id", "name", "bookable", "base_settlement_id", "notes", "updated_at")
SELECT 1, 'BetonRadar 1', true, s."id", 'W8b: bookable scanning machine, base assumed Érd (plan A1)', CURRENT_TIMESTAMP
FROM "hu_settlements" s
WHERE s."name" = 'Érd' AND s."county" = 'Pest'
  AND EXISTS (SELECT 1 FROM "tenants" WHERE "id" = 1)
  AND NOT EXISTS (SELECT 1 FROM "equipment" WHERE "tenant_id" = 1 AND "bookable" = true);
